TP.register({id:"lp1-g5",lp:1,grade:"5",mode:"baseline",nextGrade:"6th grade",build(E){const esc=E.esc;const F=E.F;const PASSAGE="Marco had practiced his speech for the science fair all week, but on Saturday morning his stomach was a tangled knot of rope. He stood beside his table, where his homemade water filter sat next to a jar of muddy creek water. The gym buzzed like a hive of bees as families moved from table to table. When the judge, a tall woman with a clipboard, finally stopped in front of him, Marco’s mind went as blank as an erased whiteboard. He glanced at his note cards, took a slow breath, and poured the brown water into the top of the filter. Drip by drip, clear water collected in the cup below. The judge raised her eyebrows and leaned closer. “How did you think of this?” she asked. “Our creek flooded last spring,” Marco said, his voice steadier now. “I wanted to know if we could clean the water ourselves.” The judge smiled and wrote something on her clipboard. Marco didn’t see what it said, but for the first time all morning, he let his shoulders drop.";const PASSAGE_N=PASSAGE.split(/\s+/).length;const TEXT_A={title:"The Long Flight",body:"Every fall, millions of monarch butterflies leave Canada and the northern United States. They fly south to the mountains of central Mexico. Some travel more than 2,500 miles. Monarchs cannot survive freezing winters, so they head to forests where the air stays cool but not icy. There, they cluster together on fir trees by the thousands. This helps them stay warm and safe from the wind."};const TEXT_B={title:"Helping Monarchs at Home",body:"Monarch caterpillars eat only one kind of plant: milkweed. Female monarchs lay their eggs on milkweed leaves. That way, the caterpillars have food as soon as they hatch. In many places, milkweed has been cleared to build roads, homes, and farms. Scientists have found that there are far fewer monarchs now than there were 30 years ago. Planting milkweed and flowers in gardens gives monarchs places to lay eggs. It also gives them nectar to drink on their long trip."};const VOLCANO="The Hawaiian Islands were built by volcanoes. Deep under the Pacific Ocean is a hot spot, where melted rock called magma pushes up through the sea floor. Each time a volcano erupts, lava cools and hardens into new rock. Over hundreds of thousands of years, the rock piled up high enough to rise above the water and form an island. The islands sit on a giant piece of Earth’s crust called the Pacific Plate, which slowly moves northwest, about as fast as your fingernails grow. As it moves, older islands drift away from the hot spot and their volcanoes stop erupting. Right now, a new volcano is growing under the ocean southeast of the Big Island. It will probably not reach the surface for thousands of years.";const WORDS=["incredible","photographer","misunderstood","unbreakable","geology","transportation","reconstruction","impossibility","responsibility","extraordinary","flemberation","unpreskable"];function twoTextsHtml(){return`<div class="texts"><article><h3>Text A: ${TEXT_A.title}</h3><p>${TEXT_A.body}</p></article><article><h3>Text B: ${TEXT_B.title}</h3><p>${TEXT_B.body}</p></article></div>`}function prism(L,W,H,s){s=s||34;const cx=Math.cos(Math.PI/6)*s,cy=Math.sin(Math.PI/6)*s;const ox=W*cx+10,oy=H*s+10;const P=(x,y,z)=>[ox+(x-y)*cx,oy+(x+y)*cy-z*s];const poly=(pts,f)=>`<polygon points="${pts.map(p=>p.map(v=>v.toFixed(1)).join(",")).join(" ")}" fill="${f}" stroke="var(--ink)" stroke-width="1.6"/>`;const cubes=[];for(let x=0;x<L;x++)for(let y=0;y<W;y++)for(let z=0;z<H;z++)cubes.push([x,y,z]);cubes.sort((a,b)=>a[0]+a[1]-(b[0]+b[1])||a[2]-b[2]);let g="";cubes.forEach(([x,y,z])=>{g+=poly([P(x,y,z+1),P(x+1,y,z+1),P(x+1,y+1,z+1),P(x,y+1,z+1)],"var(--gold)");g+=poly([P(x,y+1,z),P(x+1,y+1,z),P(x+1,y+1,z+1),P(x,y+1,z+1)],"var(--sea-soft)");g+=poly([P(x+1,y,z),P(x+1,y+1,z),P(x+1,y+1,z+1),P(x+1,y,z+1)],"var(--sea)")});const w=(L+W)*cx+20,h=(L+W)*cy+H*s+20;return`<svg viewBox="0 0 ${w.toFixed(0)} ${h.toFixed(0)}" width="${Math.min(360,w*1.3).toFixed(0)}" role="img" aria-label="Box built from unit cubes">${g}</svg>`}function grid(){const u=44,o=40,n=8;let s=`<svg viewBox="0 -16 ${o+n*u+40} ${o+n*u+56}" width="420" role="img" aria-label="Coordinate grid with points A, B, and C">`;const X=v=>o+v*u,Y=v=>o+(n-v)*u;for(let i=0;i<=n;i++){s+=`<line x1="${X(i)}" y1="${Y(0)}" x2="${X(i)}" y2="${Y(n)}" stroke="var(--line)" stroke-width="1.5"/><line x1="${X(0)}" y1="${Y(i)}" x2="${X(n)}" y2="${Y(i)}" stroke="var(--line)" stroke-width="1.5"/>`;s+=`<text x="${X(i)}" y="${Y(0)+24}" text-anchor="middle" font-size="18" fill="var(--ink)">${i}</text>`;if(i)s+=`<text x="${X(0)-14}" y="${Y(i)}" text-anchor="end" dominant-baseline="central" font-size="18" fill="var(--ink)">${i}</text>`}s+=`<line x1="${X(0)}" y1="${Y(0)}" x2="${X(n)+20}" y2="${Y(0)}" stroke="var(--ink)" stroke-width="3"/><line x1="${X(0)}" y1="${Y(0)}" x2="${X(0)}" y2="${Y(n)-20}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<text x="${X(n)+26}" y="${Y(0)+6}" font-size="20" font-weight="700" fill="var(--ink)">x</text><text x="${X(0)-6}" y="${Y(n)-28}" font-size="20" font-weight="700" fill="var(--ink)">y</text>`;[["A",3,5],["B",6,2],["C",0,4]].forEach(([l,x,y])=>{s+=`<circle cx="${X(x)}" cy="${Y(y)}" r="9" fill="var(--coral)"/><text x="${X(x)+12}" y="${Y(y)-12}" font-size="22" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">${l}</text>`});return s+"</svg>"}function grid4(){const u=34,o=30,n=5;let s=`<svg viewBox="0 -14 ${2*o+2*n*u} ${2*o+2*n*u+14}" width="400" role="img" aria-label="Coordinate grid with four quadrants and points P and Q">`;const X=v=>o+(v+n)*u,Y=v=>o+(n-v)*u;for(let i=-n;i<=n;i++){s+=`<line x1="${X(i)}" y1="${Y(-n)}" x2="${X(i)}" y2="${Y(n)}" stroke="var(--line)" stroke-width="1.5"/><line x1="${X(-n)}" y1="${Y(i)}" x2="${X(n)}" y2="${Y(i)}" stroke="var(--line)" stroke-width="1.5"/>`;if(i){s+=`<text x="${X(i)}" y="${Y(0)+18}" text-anchor="middle" font-size="14" fill="var(--ink)">${i<0?"−"+-i:i}</text><text x="${X(0)-8}" y="${Y(i)}" text-anchor="end" dominant-baseline="central" font-size="14" fill="var(--ink)">${i<0?"−"+-i:i}</text>`}}s+=`<line x1="${X(-n)-12}" y1="${Y(0)}" x2="${X(n)+12}" y2="${Y(0)}" stroke="var(--ink)" stroke-width="3"/><line x1="${X(0)}" y1="${Y(-n)+12}" x2="${X(0)}" y2="${Y(n)-12}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<text x="${X(n)+16}" y="${Y(0)+6}" font-size="18" font-weight="700" fill="var(--ink)">x</text><text x="${X(0)-5}" y="${Y(n)-16}" font-size="18" font-weight="700" fill="var(--ink)">y</text>`;[["P",-3,2],["Q",2,-4]].forEach(([l,x,y])=>{s+=`<circle cx="${X(x)}" cy="${Y(y)}" r="8" fill="var(--coral)"/><text x="${X(x)+11}" y="${Y(y)-10}" font-size="20" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">${l}</text>`});return s+"</svg>"}function areaModel(cols,rows,sc,sr,wLab,hLab){const SIDE=216,cw=SIDE/cols,ch=SIDE/rows,ox=96,oy=58,GW=SIDE,GH=SIDE,W=ox+GW+76,H=oy+GH+46;let s=`<svg viewBox="0 0 ${W} ${H}" width="${W}" style="max-width:100%;height:auto" role="img" aria-label="A square one yard on each side, cut into ${cols} columns and ${rows} rows. The block ${sc} columns wide and ${sr} rows tall in the top left corner is shaded.">`;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)s+=`<rect x="${ox+c*cw}" y="${oy+r*ch}" width="${cw}" height="${ch}" fill="${c<sc&&r<sr?"var(--gold)":"var(--surface)"}" fill-opacity="${c<sc&&r<sr?".65":"1"}" stroke="var(--fig-ink)" stroke-width="2"/>`;s+=`<rect x="${ox}" y="${oy}" width="${GW}" height="${GH}" fill="none" stroke="var(--fig-ink)" stroke-width="3.5"/>`;s+=`<path d="M${ox} ${oy-8} v-10 h${sc*cw} v10" fill="none" stroke="var(--sea)" stroke-width="2.5"/>`;s+=`<text x="${ox+sc*cw/2}" y="${oy-26}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--ink)">${wLab}</text>`;s+=`<path d="M${ox-8} ${oy} h-10 v${sr*ch} h10" fill="none" stroke="var(--sea)" stroke-width="2.5"/>`;s+=`<text x="${ox-26}" y="${oy+sr*ch/2}" font-size="18" font-weight="700" text-anchor="end" dominant-baseline="central" fill="var(--ink)">${hLab}</text>`;s+=`<text x="${ox+GW/2}" y="${oy+GH+32}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--ink)">1 yard</text>`;s+=`<text x="${ox+GW+10}" y="${oy+GH/2}" font-size="18" font-weight="700" text-anchor="start" dominant-baseline="central" fill="var(--ink)">1 yard</text>`;return s+"</svg>"}function toolOn(k){const d=document.getElementById("toolDock");return!!(d&&!d.hidden&&d.querySelector(`[data-tpk="${k}"]`))}function syncTools(){paintWords();paintPsg()}function watchDock(){const d=document.getElementById("toolDock");if(!d||d._tpWatch)return;d._tpWatch=true;new MutationObserver(syncTools).observe(d,{childList:true,attributes:true,attributeFilter:["hidden"]})}function tagNote(n,k,line){n.gen=n.gen||{};const old=n.gen[k]||"";let t=n.text||"";if(old&&t.includes(old))t=t.replace(old,()=>line);else if(line)t=(t.trim()?t.replace(/\s+$/,"")+"\n":"")+line;n.text=t.replace(/^\s+/,"").replace(/\n{3,}/g,"\n\n");n.gen[k]=line;E.save();const ft=document.getElementById("fText");if(ft)ft.value=n.text}let wordIdx=0;function wordsInner(on){const w=WORDS[wordIdx];return`<p style="text-align:center;margin:0">Word ${wordIdx+1} of ${WORDS.length}</p><p class="huge" style="font-size:${on?"clamp(2rem,4.6vw,4rem)":"clamp(2.6rem,9vw,6.5rem)"}">${on?SPLITS[w]:w}</p>
  <div class="row center"><button class="btn ghost" id="wPrev" ${wordIdx===0?"disabled":""}>Back</button><button class="btn ghost" id="wNext" ${wordIdx===WORDS.length-1?"disabled":""}>Next</button></div>`}function paintWords(){const box=document.getElementById("tpWords");if(!box)return;box.innerHTML=wordsInner(toolOn("chunk"));box.querySelector("#wPrev").onclick=()=>{wordIdx=Math.max(0,wordIdx-1);paintWords()};box.querySelector("#wNext").onclick=()=>{wordIdx=Math.min(WORDS.length-1,wordIdx+1);paintWords()}}const SENTS=PASSAGE.split(/(?<=[.!?]\u201D?)\s+(?=[A-Z\u201C])/);let rulerIdx=0,tStart=0,tInt=null;function psgInner(on){return on?SENTS.map((x,i)=>`<span class="${i===rulerIdx?"cur":""}">${x}</span>`).join(" "):PASSAGE}function paintPsg(){const el=document.getElementById("psg");if(!el)return;const on=toolOn("ruler");if(!on)rulerIdx=0;el.classList.toggle("ruler",on);el.innerHTML=psgInner(on)}const ORF5=[[179,"at or above the 90th percentile"],[153,"between the 75th and 90th percentiles"],[121,"between the 50th and 75th percentiles"],[87,"between the 25th and 50th percentiles"],[64,"between the 10th and 25th percentiles"]];function orfBand(w){for(const[cut,t]of ORF5)if(w>=cut)return t;return"below the 10th percentile"}function wordsRight(n,pi){const r=n.p&&n.p[pi]?n.p[pi].right:"";return r!==""&&r!==void 0&&r!==null&&!isNaN(+r)?Math.max(0,Math.min(PASSAGE_N,+r)):null}function wcpm(n,pi){if(!n.secs)return null;const r=wordsRight(n,pi);return Math.round((r===null?PASSAGE_N:r)*60/n.secs)}function orfText(n,pi){const w=wcpm(n,pi);if(w===null)return"";const r=wordsRight(n,pi);return`Timed read: ${n.secs} seconds, ${w} WCPM (one unpracticed read; ${r===null?"figured with no missed words, so type the words read correctly above to update it":r+" of "+PASSAGE_N+" words correct"}${(n.sup||[]).includes("ruler")?"; read with the reading ruler":""}). Hasbrouck and Tindal 2017 grade 5 fall norms: 50th percentile 121, 25th 87, 10th 64. This score is ${orfBand(w)}. For reference, the fall 50th percentile is 94 WCPM in grade 4 and 83 in grade 3.`}function readHtml(n){return`<p class="passage" id="psg">${PASSAGE}</p>
  <div class="row no-key" style="margin-top:16px;padding-top:10px;border-top:2px dashed var(--line)"><span class="small">Teacher timer</span><button class="chip" id="tGo">Start</button><button class="chip" id="tStop">Stop</button><button class="chip" id="tReset">Reset</button><strong id="tShow">${n&&n.secs?n.secs+" sec":"0 sec"}</strong></div>`}function bindRead(root,ctx){const n=ctx.note,pi=ctx.stop.parts.indexOf(ctx.part),show=root.querySelector("#tShow");const upd=()=>tagNote(n,"orf",orfText(n,pi));clearInterval(tInt);tStart=0;root.querySelector("#tGo").onclick=()=>{tStart=Date.now();clearInterval(tInt);show.textContent="0 sec";tInt=setInterval(()=>{if(!show.isConnected){clearInterval(tInt);tStart=0;return}show.textContent=Math.round((Date.now()-tStart)/1e3)+" sec"},250)};root.querySelector("#tStop").onclick=()=>{if(!tStart)return;clearInterval(tInt);n.secs=Math.max(1,Math.round((Date.now()-tStart)/1e3));tStart=0;show.textContent=n.secs+" sec";upd()};root.querySelector("#tReset").onclick=()=>{clearInterval(tInt);tStart=0;delete n.secs;show.textContent="0 sec";upd()};const inp=document.querySelector(`#stopView [data-f="right"][data-pi="${pi}"]`);if(inp)inp.addEventListener("input",()=>{if(n.secs)upd()});paintPsg();watchDock()}const METHODS=["Typed, spellcheck on","Typed, spellcheck off","Voice typing / dictation software","Handwritten","Dictated to teacher or parent (scribed)"];function writeStats(t){const w=(t.trim().match(/\S+/g)||[]).length,s=(t.match(/[^.!?]+[.!?]+/g)||[]).length;return`${w} words, about ${s} sentences`}function boxHtml(n,label){const w=n&&n.w||{};return`<div class="no-key" style="margin-top:16px"><label class="small" style="display:block">${label}<textarea class="wbox" data-wbox>${esc(w.text||"")}</textarea></label>
  <p class="small wstats" data-wstats>${w.text&&w.text.trim()?writeStats(w.text):""}</p>
  <label class="small" style="display:block;margin:6px 0 0">How the student produced the writing <select data-wmethod style="font:inherit;padding:4px 8px;border:2px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink)"><option value="">Choose</option>${METHODS.map(m=>`<option${w.method===m?" selected":""}>${m}</option>`).join("")}</select></label></div>`}function bindBox(root,ctx,what){const n=ctx.note,ta=root.querySelector("[data-wbox]"),sel=root.querySelector("[data-wmethod]"),st=root.querySelector("[data-wstats]");const upd=()=>{n.w=n.w||{};n.w.text=ta.value;n.w.method=sel.value;const has=!!ta.value.trim();st.textContent=has?writeStats(ta.value):"";tagNote(n,"w",has?`${what}. Produced by: ${sel.value||"(not recorded)"}. Length: ${writeStats(ta.value)}. """${ta.value.trim()}"""`:"")};ta.oninput=upd;sel.onchange=upd}const WDIR="Type it, use voice typing, or write on paper. Send it to your teacher or hold it up when you finish.";const STOPS=[{id:1,title:"Word Flip",parts:[{std:["RF.5.3"],dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading long words with prefixes, suffixes, and roots",kind:"words",n:12,dur:60,render:()=>{wordIdx=0;return`<div id="tpWords">${wordsInner(false)}</div>`},bind:()=>{paintWords();watchDock()},printHtml:()=>`<p><em>Words shown one at a time:</em> ${WORDS.join(", ")}</p>`,key:["Read each word. flemberation and unpreskable are made-up words: listen for how the student splits syllables and uses prefixes and suffixes (flem-ber-a-tion, un-presk-a-ble).","Watch for: prefixes and suffixes (mis-, un-, re-, -tion, -ity, -able), roots (photo, graph, geo, port), and whether the student breaks long words into chunks or guesses from the first letters."]}]},{id:2,title:"Read the Story",short:"Read",parts:[{std:["RF.5.4"],dir:"Read the story out loud at your normal speed.",desc:`a ${PASSAGE_N}-word grade-level story read aloud`,kind:"read",n:PASSAGE_N,label:"words read correctly",dur:90,render:ctx=>readHtml(ctx.note),bind:(root,ctx)=>bindRead(root,ctx),printHtml:()=>`<p class="passage">${PASSAGE}</p>`,key:[`${PASSAGE_N} words. Mark errors and self-corrections on the passage in the record sheet. Then type the number of words read correctly in Teacher notes.`,"Use the teacher timer under the passage: click Start when the student reads the first word and Stop at the last word. It figures words correct per minute (WCPM), compares it to grade 5 fall norms, and adds that line to the Notes box for this stop.","Note pace, phrasing, and expression (does the student’s voice change for the dialogue?) in your notes.","For a clean fluency baseline, time the first read without the reading ruler. If the student needs the ruler, the WCPM line says it was read with support."]}]},{id:3,title:"Story Questions",short:"Story Qs",parts:[{title:"Quote It",std:["RL.5.1"],dir:"Answer out loud. Read the exact words from the story.",desc:"quoting the story to tell what it says and to back up inferences",dur:75,html:()=>`<p class="passage sm">${PASSAGE}</p>`,qs:["Read me the exact words that show Marco was nervous at the start.","How did Marco feel at the end? Read me the words that helped you figure that out.","Why do you think the judge raised her eyebrows? Read me the words that back up your answer."],key:["Reads an exact line: “his stomach was a tangled knot of rope” or “Marco’s mind went as blank as an erased whiteboard.” (RL.5.1, explicit)","Relieved, calm, or proud. Quotes “he let his shoulders drop” or “his voice steadier now.” (RL.5.1, inference)","She was impressed or surprised the filter worked. Quotes “clear water collected in the cup below” or “leaned closer.” (RL.5.1, inference)"]},{title:"Word Pictures",std:["RL.5.4"],dir:"Answer out loud.",desc:"explaining similes and metaphors in a story",dur:45,qs:["What does “his stomach was a tangled knot of rope” mean?","“The gym buzzed like a hive of bees.” What does that tell you about the gym? Is it a simile or a metaphor?","What does “as blank as an erased whiteboard” mean?"],key:["He was very nervous. (RL.5.4, metaphor)","It was busy and noisy. Simile, because it uses like. (RL.5.4)","He couldn’t remember what to say. (RL.5.4)"]}]},{id:4,title:"Place Value Power",short:"Place Value",parts:[{std:["5.NBT.A.1"],dir:"Look at the numbers. Answer out loud.",desc:"comparing the value of a digit in two places (10 times as much and 1/10)",dur:50,fig:()=>`<p class="huge" style="font-size:clamp(2.6rem,6.5vw,5.2rem)">5,555 &nbsp; 0.44</p>`,qs:["In 5,555, how does the 5 in the hundreds place compare to the 5 in the tens place?","In 0.44, how does the 4 in the tenths place compare to the 4 in the hundredths place?","The 3 in 30 is what fraction of the 3 in 300?"],key:["It is 10 times as much (500 vs 50). Partial: naming the two values with no comparison is approaching. (5.NBT.A.1)","10 times as much (0.4 vs 0.04). Partial: naming the two values with no comparison is approaching. (5.NBT.A.1)","1/10 (30 is 1/10 of 300). Partial: 10 times as much reverses the comparison and does not count. (5.NBT.A.1)"]}]},{id:5,title:"Decimal Detective",short:"Decimals",parts:[{std:["5.NBT.A.3"],dir:"Say number 1 out loud. Write the rest on your paper and hold it up.",desc:"reading, writing, and comparing decimals to thousandths",dur:75,qs:["Read this number out loud: 4.307","Write 2.564 in expanded form.","Write this as a number: six and forty-two thousandths.","Which is greater: 0.45 or 0.405? Use &gt; or &lt;."],key:["Four and three hundred seven thousandths. Partial: four point three zero seven is approaching, since the place value name is what is asked. (5.NBT.A.3)","2 × 1 + 5 × (1/10) + 6 × (1/100) + 4 × (1/1000), or 2 + 0.5 + 0.06 + 0.004. Partial: three of the four places written is approaching. (5.NBT.A.3)","6.042. Partial: 6.42 puts the digits in the wrong places and does not count. (5.NBT.A.3)","0.45 &gt; 0.405. Or: compare 450 thousandths against 405 thousandths. Partial: the right choice with the sign the wrong way round is approaching. (5.NBT.A.3)"]}]},{id:6,title:"Bracket Puzzles",short:"Brackets",parts:[{std:["5.OA.A.1"],dir:"Solve each one on your paper. Tell your teacher your answers.",desc:"evaluating expressions with parentheses, brackets, and braces",dur:80,qs:["2 × (6 + 4) = ?","20 − [3 × (2 + 1)] = ?","{4 + [10 ÷ (3 + 2)]} × 3 = ?","Add parentheses to make this true: 3 + 5 × 2 = 16"],key:["20. Partial: 16 comes from multiplying before adding and does not count. (5.OA.A.1)","11. Partial: 51 comes from working left to right and does not count. (5.OA.A.1)","18. Partial: 10 comes from multiplying before the braces are cleared and does not count. (5.OA.A.1)","(3 + 5) × 2 = 16. Partial: 3 + (5 × 2) puts the parentheses in the wrong place and does not count. (5.OA.A.1)"]}]},{id:7,title:"Fraction Mix",short:"Fractions",parts:[{title:"Add and Subtract",std:["5.NF.A.1"],dir:"Solve on your paper. Show your work and hold it up.",desc:"adding and subtracting fractions and mixed numbers with unlike denominators",dur:105,qs:["1/2 + 1/3 = ?","3/4 − 1/6 = ?","2 1/2 + 1 1/4 = ?"],key:["5/6. Or: twelfths work too, 6/12 + 4/12 = 10/12 = 5/6. Partial: 2/5 comes from adding across and does not count. (5.NF.A.1)","7/12. Partial: subtracting across, numerator from numerator and denominator from denominator, does not count. (5.NF.A.1)","3 3/4. Or: change to quarters first, 10/4 + 5/4 = 15/4. Partial: 3 2/6 comes from adding across and does not count. (5.NF.A.1)"]},{title:"Fraction Word Problems",std:["5.NF.A.2"],dir:"Solve the first problem on your paper. Explain the second one out loud.",desc:"a fraction addition word problem and a benchmark fraction check",dur:75,qs:["Ana ran 3/4 of a mile on Monday and 2/3 of a mile on Tuesday. How far did she run in all?","Eli says 2/5 + 1/2 = 3/7. Without solving, how can you tell he is wrong?"],key:["17/12, or 1 5/12 miles. Shows a model or equation. Or: twenty-fourths work too, 18/24 + 16/24 = 34/24. Partial: the model right with no total is approaching. (5.NF.A.2)","3/7 is less than 1/2, but he added something to 1/2, so the answer has to be more than 1/2. Partial: saying he is wrong with no benchmark used is approaching. (5.NF.A.2, benchmark fractions)"]}]},{id:8,title:"Share It",parts:[{title:"Fractions as Division",std:["5.NF.B.3"],dir:"Solve on your paper. Tell your teacher your answers.",desc:"division word problems with fraction and mixed number answers",dur:60,qs:["3 pizzas are shared equally by 4 kids. How much pizza does each kid get?","20 pounds of rice are shared equally by 6 people. How many pounds does each person get? Between what two whole numbers is your answer?"],key:["3/4 of a pizza. Or: 3 ÷ 4 written as a division counts equally. Partial: 4/3 reverses the share and does not count. (5.NF.B.3)","3 1/3 pounds, between 3 and 4. Partial: 3 1/3 right with no pair of whole numbers named is approaching. (5.NF.B.3)"]},{title:"Multiply Fractions",std:["5.NF.B.4"],dir:"Solve on your paper. Tell your teacher your answers. The last question goes with the square picture.",desc:"multiplying fractions and whole numbers by fractions, including the area of a rectangle with fractional sides",dur:115,qs:["2/3 × 6 = ?","3/4 × 2/5 = ?","What is 1/2 of 3/4?","The square in the picture is one square yard, cut into fourths across and thirds down. The shaded block is 3/4 of a yard by 2/3 of a yard. What is its area in square yards? Use the small rectangles in the picture to show why."],fig2:()=>`<div class="figure"><div style="text-align:center">${areaModel(4,3,3,2,"3/4 yd","2/3 yd")}<p class="fig-label" style="margin:4px 0 0">The planted corner</p></div></div>`,key:["4. Or: 6 ÷ 3 = 2, then 2 × 2 = 4. (5.NF.B.4)","6/20 or 3/10. Or: a 4 by 5 area model with 6 of the 20 squares shaded. (5.NF.B.4)","3/8. Or: write it as 1/2 × 3/4 and multiply. (5.NF.B.4)","1/2 of a square yard. Cutting the square into 4 columns and 3 rows makes 12 small rectangles, and each one is 1/12 of a square yard. The shaded block covers 3 columns by 2 rows, which is 6 of them, and 6/12 = 1/2. In numbers, 3/4 × 2/3 = 6/12 = 1/2. Partial: 6/12 right with no simpler form, or with no use of the picture, is approaching. (5.NF.B.4b, area by tiling with unit fraction pieces)"]}]},{id:9,title:"Box Builder",short:"Volume",parts:[{title:"What Is Volume?",std:["5.MD.C.3"],dir:"Look at the box. Answer out loud.",desc:"counting unit cubes for volume and telling what volume measures",dur:40,fig:()=>`<div class="figure">${prism(3,2,2)}</div>`,qs:["Each cube is 1 cubic unit. What is the volume of this box? Say the units.","What does volume measure?"],key:["12 cubic units. Partial: 12 with no unit named is approaching. (5.MD.C.3)","The space a solid takes up, or how many unit cubes fill it with no gaps. Partial: naming the space with nothing said about unit cubes is approaching. (5.MD.C.3)"]},{title:"Find the Volume",std:["5.MD.C.5"],dir:"Solve on your paper. Tell your teacher your answers.",desc:"finding volume by multiplying and by adding the volumes of two boxes",dur:75,qs:["Show how to find the volume of the box in the picture using multiplication.","A box is 4 cm long, 3 cm wide, and 5 cm tall. What is its volume?","A shape is made of two boxes: one is 2 by 2 by 3, and the other is 4 by 1 by 2. What is the total volume?"],key:["3 × 2 × 2 = 12, or base 6 × height 2 = 12. Partial: the right total with no multiplication shown is approaching. (5.MD.C.5)","60 cubic cm. Or: 4 × 3 = 12 for the base, then 12 × 5. Partial: 60 with no unit named is approaching. (5.MD.C.5)","12 + 8 = 20 cubic units. Partial: one of the two boxes worked out is approaching. (5.MD.C.5, volume is additive)"]}]},{id:10,title:"Grid Hunt",parts:[{std:["5.G.A.1"],dir:"Look at the grid. Answer out loud.",desc:"naming the origin, the axes, and the coordinates of points on a grid",dur:60,fig:()=>`<div class="figure">${grid()}</div>`,qs:["Where is the origin on this grid? What are its coordinates?","What are the coordinates of point A?","Which point is at (6, 2)?","Which axis do you move along first when you find a point?","Point C is at (0, 4). Why is the first number 0?"],key:["(0, 0), the corner where the x-axis and y-axis meet. Partial: (0, 0) with no account of where it sits is approaching. (5.G.A.1)","(3, 5). Partial: (5, 3) reverses the pair and is approaching. (5.G.A.1)","B (5.G.A.1)","The x-axis, the one going across (5.G.A.1)","It is on the y-axis, so you don’t move across at all. Partial: naming the y-axis with nothing said about not moving across is approaching. (5.G.A.1)"]}]},{id:11,title:"Grammar Fix",short:"Grammar",parts:[{std:["L.5.1"],dir:"Say each sentence out loud the correct way. For the last one, say the words you find.",desc:"spoken grammar items (verb tenses, either/or, parts of speech)",dur:75,qs:["Fix it: “Yesterday I walk to the park and saw a hawk.”","Finish it: “By the time we got there, the movie ____ (start).”","Finish it: “By Friday, I ____ (finish) my project.”","Use either/or: “Marco could present first. Jade could present first.” Only one of them will.","“Wow, the monarchs flew over the mountains and into Mexico!” Find the interjection, a preposition, and the conjunction."],key:["walked (L.5.1, fixing a tense shift)","had started (L.5.1, past perfect)","will have finished (L.5.1, future perfect)","Either Marco or Jade will present first. (L.5.1, correlative conjunctions)","Wow; over or into; and (L.5.1)"]}]},{id:12,title:"Two Texts",parts:[{title:"Quote the Text",std:["RI.5.1"],dir:"Read both texts to yourself. Then answer out loud with the exact words from the text.",desc:"quoting an informational text to tell what it says and to back up an inference",dur:100,html:()=>twoTextsHtml(),qs:["Read me the sentence from Text A that tells why monarchs fly south.","Why is losing milkweed a problem for monarchs? Read me the words from Text B that back up your answer."],key:["“Monarchs cannot survive freezing winters, so they head to forests where the air stays cool but not icy.” (RI.5.1, explicit)","Caterpillars only eat milkweed, so without it there is nowhere to lay eggs and nothing for caterpillars to eat. Quotes “Monarch caterpillars eat only one kind of plant: milkweed” or the egg-laying sentence. (RI.5.1, inference)"]},{title:"Quick Notes",std:["W.5.8"],dir:"Write your notes on paper or type them. Hold them up or send them to your teacher.",desc:"notes in the student’s own words from two texts with a list of sources",n:3,label:"checks met",dur:90,html:()=>`<p class="big" style="font-size:1.5rem">Jot 3 short notes about monarchs in your own words. Words and phrases are fine, no full sentences. Put A or B after each note. Then write the two titles at the bottom as your sources.</p>`,render:ctx=>boxHtml(ctx.note,"Notes and sources (paste or type here)"),bind:(root,ctx)=>bindBox(root,ctx,"Student notes"),key:["3 notes with the key facts from the texts (W.5.8)","Notes are in the student’s own words, not copied word for word (W.5.8)","Labels A or B and writes both titles as a list of sources (W.5.8)"]},{title:"Put It Together",std:["RI.5.9"],dir:"Answer out loud. Use ideas from both texts.",desc:"putting together information from two texts on the same topic",dur:110,qs:["Using both texts, tell me what monarchs need to survive their journey.","Text A says monarchs fly more than 2,500 miles south. Text B says milkweed and flowers have been cleared to build roads, homes and farms. Put those two facts together. Why does that clearing make the long flight harder?","Say you wrote one paragraph about why there are far fewer monarchs now. Name one idea from each text you would use. Say why each one matters."],key:["Combines both texts out loud: warm-enough forests in Mexico and fir trees to cluster on (A), plus milkweed for eggs and flowers for nectar along the way (B). Needs at least one idea from each text. (RI.5.9)","The trip is more than 2,500 miles (A) and Text B says gardens give monarchs nectar to drink on their long trip, so clearing the plants leaves fewer places to feed and lay eggs along the whole route. Needs the length of the journey from A and the loss of plants from B, not just one of them. (RI.5.9)","From B: caterpillars eat only milkweed, milkweed has been cleared, and there are far fewer monarchs than 30 years ago. From A: they cannot survive freezing winters and depend on one set of mountain forests, so they cannot simply spend the winter somewhere else. One idea from each text, each with a reason. (RI.5.9)"]}]},{id:13,title:"Listen and Sum Up",short:"Listen",parts:[{std:["SL.5.2"],dir:"Listen while your teacher reads. Then sum it up out loud in your own words.",desc:"summarizing a text read aloud",n:4,label:"checks met",dur:95,html:()=>`<p class="huge" aria-hidden="true">${F.icon("volcano",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about how the Hawaiian Islands formed. Then sum it up in a few sentences.</p>`,read:VOLCANO,key:["Gives the main idea: volcanoes over a hot spot built the islands (SL.5.2)","Includes 2 or more key details: lava hardens and piles up; the plate moves so older islands drift off and stop erupting; a new volcano is growing underwater (SL.5.2)","Keeps the order and uses the student’s own words (SL.5.2)","Keeps it short, no extra opinions or small details (SL.5.2)"]}]},{id:14,title:"Opinion Talk",short:"Opinion",parts:[{std:["SL.5.4"],dir:"Pick one question. Plan for 1 minute. Then tell your opinion and your reasons out loud.",desc:"presenting an opinion out loud with reasons and details",n:6,label:"checks met",dur:90,html:()=>`<p class="big">Pick one and tell me what you think. Take 1 minute to plan.</p><ul class="qlist" style="margin-top:14px"><li>Should every kid learn to cook before middle school?</li><li>Is it better to have a pet dog or a pet cat?</li></ul><div class="row center" style="margin-top:20px;gap:14px"><span class="pill" style="font-size:1.2rem">My opinion</span><span class="pill" style="font-size:1.2rem">Reason 1</span><span class="pill" style="font-size:1.2rem">Reason 2</span><span class="pill" style="font-size:1.2rem">So...</span></div>`,key:["States a clear opinion (SL.5.4)","Gives reasons in a logical order (SL.5.4)","Backs reasons with facts or examples (SL.5.4)","Uses transition words like for example, also, therefore, consequently (SL.5.4)","Ends with a concluding statement (SL.5.4)","Speaks clearly at an understandable pace (SL.5.4)"]}]},{id:15,title:"Writer’s Choice",short:"Write",parts:[{alt:{group:"write",label:"Opinion",icon:"💬",hint:"Write the opinion you just told me"},std:["W.5.1","L.5.1"],dir:WDIR,desc:"an opinion writing piece",n:6,label:"checks met",dur:180,html:()=>`<p class="big">Write down the opinion you just told me. 4 or 5 sentences. You can type it or say it with voice typing.</p><ul class="qlist" style="margin-top:14px"><li>Say your opinion</li><li>Give 2 reasons with an example</li><li>Use a linking word</li><li>End with a closing sentence</li></ul>`,render:ctx=>boxHtml(ctx.note,"Opinion writing (paste or type here)"),bind:(root,ctx)=>bindBox(root,ctx,"Student writing"),key:["Introduces the topic and states an opinion (W.5.1)","Reasons are in a logical order (W.5.1)","Reasons are supported with facts or details (W.5.1)","Links opinion and reasons with words like for example, specifically, consequently (W.5.1)","Has a concluding sentence (W.5.1)","Verb tenses stay consistent and correct (L.5.1)"]},{alt:{group:"write",label:"Explain It",icon:"🌋",hint:"Teach about volcanoes or monarchs"},std:["W.5.2"],dir:WDIR,desc:"an informative writing piece",n:6,label:"checks met",dur:300,html:()=>`<p class="big">Pick one. Explain it to someone who has never heard of it. Use what you read or heard today. 5 to 7 sentences. Type it or use voice typing.</p><ul class="qlist" style="margin-top:14px"><li>${F.icon("volcano",26)} How the Hawaiian Islands formed</li><li>${F.icon("butterfly",26)} What monarch butterflies need to survive their trip</li></ul>`,render:ctx=>boxHtml(ctx.note,"Informative writing (paste or type here)"),bind:(root,ctx)=>bindBox(root,ctx,"Student writing"),key:["Introduces the topic clearly (a title or heading counts as formatting) (W.5.2)","Groups related facts together in a logical order (W.5.2)","Develops the topic with facts, definitions, or details (W.5.2)","Links ideas with words like also, for example, in contrast, especially (W.5.2)","Uses topic words correctly (magma, lava, hot spot, plate or milkweed, migrate, nectar) (W.5.2)","Ends with a concluding sentence (W.5.2)"]},{alt:{group:"write",label:"Tell a Story",icon:"📖",hint:"A time you were nervous"},std:["W.5.3"],dir:WDIR,desc:"a narrative writing piece",n:6,label:"checks met",dur:300,html:()=>`<p class="big">Write about a time you were nervous about something and it turned out okay. It can be real or made up. 5 to 8 sentences. Type it or use voice typing.</p><div class="row center" style="margin-top:20px;gap:14px"><span class="pill" style="font-size:1.2rem">Beginning</span><span class="pill" style="font-size:1.2rem">Middle</span><span class="pill" style="font-size:1.2rem">End</span></div>`,render:ctx=>boxHtml(ctx.note,"Narrative writing (paste or type here)"),bind:(root,ctx)=>bindBox(root,ctx,"Student writing"),key:["Sets up the situation and introduces the narrator or characters (W.5.3)","Events unfold in a clear order (W.5.3)","Uses dialogue or description to show how characters feel or react (W.5.3)","Uses transition words to show time (first, later, after that, finally) (W.5.3)","Uses concrete or sensory details (what the writer saw, heard, felt) (W.5.3)","Ends with a conclusion that follows from the events (W.5.3)"]}]},{id:16,title:"Matter Too Small to See",short:"Tiny Bits",parts:[{std:["5-PS1-1"],n:3,dur:75,dir:"Look at the picture. Answer out loud.",desc:"using a model of particles too small to be seen to explain what happens to matter",html:()=>`<p class="big">In the ship's galley a crew member stirs a spoonful of sugar into a mug of water. The water turns clear again and the sugar cannot be seen anywhere.</p>
     <div class="figure">${F.icon("drop",88)}${F.icon("gem",88)}</div>
     <p class="big">Scientists explain this by saying that matter is made of particles far too small for your eyes to see.</p>`,qs:["Did the sugar disappear, or is it still in the mug? How could you find out?","Use the idea of particles too small to see. Explain what happened to the sugar.","Someone cooks below deck and you can smell it up on deck. How does the same idea explain that?"],key:["It is still there. Tasting the water would show it, and the mug would still weigh the same as the water plus the sugar did before. (5-PS1-1)","The sugar broke apart into particles too small to see and spread out in the spaces between the water particles. It is still in the mug, just invisible. (5-PS1-1)","Particles from the food spread out through the air and travel until they reach your nose. Air is matter made of particles too, even though you cannot see it. (5-PS1-1)"]},{std:["5-PS1-3"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"identifying materials from measured properties rather than from appearance",html:()=>`<p class="big">Four unlabeled pieces came out of a sea chest. The crew tested each one and wrote down what they found.</p>
     <table class="bigTable"><tr><th>Piece</th><th>Floats?</th><th>Pulled by a magnet?</th><th>Scratches glass?</th></tr>
     <tr><td>W</td><td>yes</td><td>no</td><td>no</td></tr>
     <tr><td>X</td><td>no</td><td>yes</td><td>no</td></tr>
     <tr><td>Y</td><td>no</td><td>no</td><td>yes</td></tr>
     <tr><td>Z</td><td>no</td><td>no</td><td>no</td></tr></table>
     <p class="big">The four materials are cork, iron, quartz, and a lump of clay.</p>`,qs:["Which piece is the iron? Name the test that told you.","Which piece is the cork? Name the test that told you.","Pieces Y and Z both sink and neither is magnetic. Which test separates them, and which piece is the quartz?"],key:["X, because it was the only one a magnet pulled. (5-PS1-3)","W, because it was the only one that floated. (5-PS1-3)","The scratch test. Y scratches glass, so Y is the quartz and Z is the clay. Properties, not looks, are what identify a material. (5-PS1-3)"]}]},{id:17,title:"Weighing and Mixing",short:"Weigh In",parts:[{std:["5-PS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"using measurements to show that total weight is conserved through heating, cooling, and mixing",html:()=>`<p class="big">The crew sealed three jars, weighed each one, left them on deck all day, then weighed them again. Nothing was added and nothing was let out.</p>
     <table class="bigTable"><tr><th>Sealed jar</th><th>What was inside</th><th>Weight at dawn</th><th>Weight at dusk</th></tr>
     <tr><td>1</td><td>a lump of ice</td><td>240 g</td><td>240 g</td></tr>
     <tr><td>2</td><td>water and a spoon of salt, stirred</td><td>186 g</td><td>?</td></tr>
     <tr><td>3</td><td>wet sand, left in the sun</td><td>315 g</td><td>?</td></tr></table>`,qs:["Jar 1 held ice at dawn and water at dusk, and the weight did not change. Why not?","What should jar 2 weigh at dusk? Explain your answer.","The sand in jar 3 looks dry at dusk and the lid is foggy inside. What does jar 3 weigh now?"],key:["The matter is all still in the sealed jar. Melting changes how the particles are arranged, not how many there are, so the weight stays the same. (5-PS1-2)","186 g. Dissolving spreads the salt out among the water particles. No matter left the jar, so the total weight is unchanged. (5-PS1-2)","315 g. The water left the sand and became water vapor, but the vapor is still inside the sealed jar. Weight is conserved through heating too. (5-PS1-2)"]},{std:["5-PS1-4"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"deciding from evidence whether mixing two substances made a new substance",html:()=>`<p class="big">Two mixings, done on the same table, with notes on what happened.</p>
     <table class="bigTable"><tr><th>Mixing</th><th>What the crew saw</th></tr>
     <tr><td>sand stirred into water</td><td>The water went cloudy, then the sand settled on the bottom. Poured through a cloth, the sand came back dry and unchanged.</td></tr>
     <tr><td>baking soda stirred into vinegar</td><td>It fizzed hard, the cup felt cooler, and the bubbles put out a lit match held above the cup. Nothing like either starting material was left.</td></tr></table>`,qs:["Which mixing made a new substance? Give two pieces of evidence from the chart.","Which mixing did not make a new substance? How do you know?","What would you do to test whether mixing two more substances made something new?"],key:["Baking soda and vinegar. Evidence: it fizzed, which means a gas formed, the temperature changed, the gas put out a flame, and nothing like the starting materials was left. (5-PS1-4)","Sand and water, because the sand came back out of the cloth dry and unchanged. Getting the starting materials back shows they were only mixed, not changed. (5-PS1-4)","Record a property of each substance first, then mix them and look for a gas, a color change, a temperature change, or a solid forming, and try to separate the starting materials back out. (5-PS1-4)"]}]},{id:18,title:"Plants, Food and the Sun",short:"Plant Food",parts:[{std:["5-LS1-1"],n:3,dur:70,dir:"Read the chart. Answer out loud.",desc:"arguing from measurements that plants get their material for growth from air and water",html:()=>`<p class="big">A palm seedling was planted in a weighed pot of dry soil and given nothing but water and sunlight for one year.</p>
     <div class="figure">${F.icon("sprout",80)}${F.icon("palm",80)}${F.icon("sun",80)}</div>
     <table class="bigTable"><tr><th></th><th>At planting</th><th>One year later</th></tr>
     <tr><td>The plant</td><td>12 g</td><td>940 g</td></tr>
     <tr><td>The dry soil</td><td>2,000 g</td><td>1,994 g</td></tr></table>`,qs:["How much weight did the plant gain? How much did the soil lose?","The plant gained far more than the soil lost. So where did almost all of that new material come from?","Someone says the plant ate the soil as food. What in the chart shows that cannot be the whole answer?"],key:["The plant gained 928 g. The soil lost 6 g. (5-LS1-1)","From air and water. The plant takes in carbon dioxide from the air and water through its roots and builds its own material from them, using energy from sunlight. (5-LS1-1)","The soil lost only 6 g while the plant gained 928 g. There is nowhere near enough missing soil to account for the growth. (5-LS1-1)"]},{std:["5-PS3-1"],n:3,dur:70,dir:"Look at the chain. Answer out loud.",desc:"using a model to trace the energy in an animal's food back to the sun",html:()=>`<p class="big">On the island, this is one path that energy takes.</p>
     <p class="huge" style="font-size:2.2rem;margin:10px 0;text-align:center">${F.icon("sun",46)} &rarr; ${F.icon("herb",46)} &rarr; ${F.icon("goat",46)} &rarr; ${F.icon("fox",46)}</p>
     <p class="big">A goat eats island grass. A fox eats the goat.</p>`,qs:["The goat uses energy to grow, to move, and to stay warm. Where did that energy come from before it was in the grass?","The fox never eats a plant. Explain how energy from the sun still reaches the fox.","Could this chain start with the goat instead of the sun? Why or why not?"],key:["From the sun. The grass captured sunlight and stored that energy in the food it made, and the goat got the energy by eating the grass. (5-PS3-1)","The grass stored energy from sunlight, the goat ate the grass and stored some of that energy in its body, and the fox got it by eating the goat. Every step passes along energy that started as sunlight. (5-PS3-1)","No. Animals cannot make their own food, so the energy has to come in from outside the chain, and that is sunlight captured by plants. (5-PS3-1)"]}]},{id:19,title:"Where the Matter Goes",short:"Matter Cycle",parts:[{std:["5-LS2-1"],n:4,dur:90,dir:"Look at the model. Answer out loud.",desc:"describing with a model how matter moves among plants, animals, decomposers, and the environment",html:()=>`<p class="big">A model of one patch of the island. The arrows show matter moving.</p>
     <table class="bigTable"><tr><th>From</th><th>To</th><th>How</th></tr>
     <tr><td>air and soil</td><td>palm tree</td><td>the tree takes in water, carbon dioxide, and minerals</td></tr>
     <tr><td>palm tree</td><td>land crab</td><td>the crab eats fallen fruit</td></tr>
     <tr><td>crab and fallen leaves</td><td>fungi and bacteria</td><td>decomposers break down what has died</td></tr>
     <tr><td>fungi and bacteria</td><td>air and soil</td><td>?</td></tr></table>
     <div class="figure">${F.icon("palm",72)}${F.icon("crab",72)}${F.icon("mushroom",72)}${F.icon("leaf",72)}</div>`,qs:["What belongs in the last box, where the arrow goes from the decomposers back to the air and soil?","What is a decomposer? Name the two in this model.","Suppose every decomposer on the island vanished. Describe two things that would happen to this patch.","Is this a line or a circle? Explain your answer using the arrows."],key:["The decomposers release material back into the soil and the air as they break things down, so the minerals and gases become available to plants again. (5-LS2-1)","A living thing that breaks down dead material. In this model, fungi and bacteria. (5-LS2-1)","Dead leaves, fruit, and animals would pile up instead of breaking down, and the soil would run short of the minerals plants need, so the plants would grow poorly and the animals that eat them would have less food. (5-LS2-1)","A circle. The last arrow returns matter to the air and soil, which is where the first arrow started, so the same matter is used again and again. (5-LS2-1)"]}]},{id:20,title:"Which Way Is Down",short:"Down",parts:[{std:["5-PS2-1"],n:3,dur:70,dir:"Answer out loud.",desc:"arguing that the gravitational force Earth exerts on objects is directed down",html:()=>`<p class="big">A sailor drops a coin from the top of the mast. Below, a weight hangs from a string over the side of the deck.</p>
     <div class="figure">${F.icon("coin",80)}${F.icon("anchor",80)}${F.icon("pirateShip",88)}</div>`,qs:["Which way does the dropped coin travel? Which way does the hanging string point?","A ship on the far side of the world is upside down compared with this one. Does a coin dropped there fall up, toward this ship? Explain.","A sailor says things fall because air pushes them down. Give one reason that cannot be the explanation."],key:["Both go straight down, toward the ground. (5-PS2-1)","No. It falls down from where that sailor stands, which is toward the center of Earth. Down means toward Earth's center everywhere, so down points a different direction in space at each place on the globe. (5-PS2-1)","Things also fall where there is almost no air, such as high above the ground or on the airless moon, and a heavy stone falls through air rather than being held up by it. The pull comes from Earth, not from the air. (5-PS2-1)"]},{std:["5-ESS2-1"],n:3,dur:75,dir:"Read the story of the storm. Answer out loud.",desc:"describing with an example how the geosphere, biosphere, hydrosphere, and atmosphere interact",html:()=>`<p class="big">Four parts of the Earth system: the geosphere is the rock and soil, the biosphere is all the living things, the hydrosphere is all the water, and the atmosphere is the air.</p>
     <p class="big">A storm crosses the island. Rain falls hard on a bare hillside. Soil washes down a gully into the bay and clouds the water. Where palm roots hold the ground, almost no soil moves. The rain soaks in there and the trees take it up.</p>
     <div class="figure">${F.icon("rain",76)}${F.icon("mountain",76)}${F.icon("palm",76)}${F.icon("wave",76)}</div>`,qs:["Name the two spheres that interact when rain from the air falls on rock and soil.","Soil washes into the bay and clouds the water. Which spheres are interacting there?","Pick one interaction in the story that involves the biosphere. Say which spheres it connects and what happens."],key:["The atmosphere and the geosphere. Water from the air lands on the rock and soil and carries some of it away. (5-ESS2-1)","The geosphere and the hydrosphere. Material from the land moves into the water of the bay and changes it. (5-ESS2-1)","Any one of these: palm roots, which are biosphere, hold the geosphere in place so less soil moves; the trees take up water, which connects biosphere and hydrosphere; the clouded bay water affects the living things in it, connecting hydrosphere and biosphere. (5-ESS2-1)"]}]},{id:21,title:"Stars and Shadows",short:"Sky",parts:[{std:["5-ESS1-1"],n:3,dur:70,dir:"Read the chart. Answer out loud.",desc:"arguing that the sun looks brightest because of how near it is, not because it gives off the most light",html:()=>`<p class="big">Three stars, with how much light each one really gives off and how far away it is. A light-year is the distance light travels in one year.</p>
     <table class="bigTable"><tr><th>Star</th><th>Light it gives off</th><th>Distance from Earth</th><th>How bright it looks from here</th></tr>
     <tr><td>the sun</td><td>1 unit</td><td>8 light-minutes</td><td>brightest by far</td></tr>
     <tr><td>Sirius</td><td>25 units</td><td>8.6 light-years</td><td>a bright point</td></tr>
     <tr><td>Rigel</td><td>about 100,000 units</td><td>860 light-years</td><td>a faint point</td></tr></table>
     <div class="figure">${F.icon("sun",80)}${F.icon("star",80)}${F.icon("telescope",80)}</div>`,qs:["Which star on the chart gives off the most light? Which one looks brightest from Earth?","Use the distance column to explain why those are not the same star.","Rigel gives off far more light than Sirius but looks fainter. What does that tell you about using how bright a star looks to judge how much light it really makes?"],key:["Rigel gives off the most light. The sun looks brightest from Earth. (5-ESS1-1)","The sun is only 8 light-minutes away while Sirius is 8.6 light-years and Rigel is 860 light-years away. Light spreads out as it travels, so a near star looks far brighter than a distant one even when the distant one makes much more light. (5-ESS1-1)","How bright a star looks cannot tell you on its own. You need its distance too, because apparent brightness depends on both how much light the star makes and how far away it is. (5-ESS1-1)"]},{std:["5-ESS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"finding patterns in graphed data about shadows, day length, and the night sky",html:()=>`<p class="big">The crew drove a stick into the sand and measured its shadow all day.</p>
     <table class="bigTable"><tr><th>Time</th><th>Shadow length</th><th>Shadow points</th></tr>
     <tr><td>7 a.m.</td><td>96 cm</td><td>west</td></tr>
     <tr><td>10 a.m.</td><td>38 cm</td><td>northwest</td></tr>
     <tr><td>noon</td><td>14 cm</td><td>north</td></tr>
     <tr><td>3 p.m.</td><td>44 cm</td><td>northeast</td></tr>
     <tr><td>6 p.m.</td><td>104 cm</td><td>east</td></tr></table>`,qs:["Describe the pattern in the shadow length across the day.","The shadow swings from west to east. What is moving to cause that?","They also noticed that a group of stars overhead in the autumn was not overhead in the spring. What causes that yearly change?"],key:["It is longest in the early morning and the late afternoon and shortest around noon. It shortens until midday, then lengthens again. (5-ESS1-2)","Earth is spinning on its axis, so the sun appears to move across the sky from east to west and the shadow swings the opposite way. (5-ESS1-2)","Earth travels around the sun during the year, so at night we face a different part of space in different seasons and see different stars. (5-ESS1-2)"]}]},{id:22,title:"Earth's Water",short:"Water",parts:[{std:["5-ESS2-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"describing the amounts and percentages of water and fresh water in Earth's reservoirs",html:()=>`<p class="big">Where all of Earth's water sits.</p>
     <table class="bigTable"><tr><th>Reservoir</th><th>Share of all water</th></tr>
     <tr><td>the oceans, which are salty</td><td>about 97%</td></tr>
     <tr><td>ice caps and glaciers</td><td>about 2%</td></tr>
     <tr><td>groundwater</td><td>about 1%</td></tr>
     <tr><td>lakes, rivers, soil, and the air</td><td>less than 1%</td></tr></table>`,qs:["About what percentage of Earth's water is salty ocean water? About what percentage is fresh?","Most of the fresh water is not easy for people to use. Which reservoir holds most of it, and why is that hard to use?","If you drew a bar graph of this chart, what would it look like? Describe the bars."],key:["About 97% is salty ocean water and about 3% is fresh. (5-ESS2-2)","Ice caps and glaciers hold about 2% of all water, which is most of the fresh water. It is frozen solid and far from where most people live. (5-ESS2-2)","One bar reaching nearly the whole way up for the oceans, and three bars so short they are hard to see for ice, groundwater, and surface water. Lakes and rivers would barely show at all. (5-ESS2-2)"]},{std:["5-ESS3-1"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"combining information about ways communities use science to protect resources and the environment",html:()=>`<p class="big">Two island villages are short of fresh water. Each tried something different.</p>
     <table class="bigTable"><tr><th>Village</th><th>What they did</th><th>Result after one year</th></tr>
     <tr><td>North Cove</td><td>Put gutters and storage tanks on every roof to catch rainwater</td><td>Well use dropped by half in the rainy months</td></tr>
     <tr><td>South Cove</td><td>Planted trees along the stream and fenced the animals away from the bank</td><td>The stream ran clearer and kept running later into the dry season</td></tr></table>`,qs:["How does catching rain off a roof protect the village well?","South Cove planted trees along the stream. Name two ways that helps the water.","Combine the two reports. What advice would you give a third village that has both problems?"],key:["Rain that would have run off is used instead, so less water is pumped out of the well and the groundwater has time to refill. (5-ESS3-1)","Roots hold the soil so less of it washes into the stream, which keeps the water clearer, and shade and soil that soaks up rain release water slowly so the stream keeps running longer. Keeping animals off the bank also stops the bank being trampled. (5-ESS3-1)","Do both: catch rain off the roofs to cut how much is taken from the well, and plant along the stream and keep animals off the bank to keep the stream clean and running. The answer has to use something from each report. (5-ESS3-1)"]}]},{id:23,title:"Design a Rain Catcher",short:"Design It",parts:[{std:["3-5-ETS1-1"],n:3,dur:60,dir:"Listen, then answer out loud.",desc:"defining a design problem with criteria for success and constraints",read:"The expedition camp has run low on fresh water. It rains most afternoons, but the rain runs off the tent and soaks into the sand. The crew wants something that catches rainwater and holds it clean until evening. They have one afternoon to build it, and they can only use what is already in camp: canvas, rope, two buckets, and a few poles.",qs:["In one sentence, what is the problem that needs solving?","Name two things the finished catcher must do to count as a success.","Name two limits the crew has to work inside."],key:["Rain is falling but running off and soaking away, so the camp needs a way to catch and keep clean rainwater. (3-5-ETS1-1)","Any two criteria from the story: it has to catch rain rather than let it run off, hold the water until evening, and keep the water clean. (3-5-ETS1-1)","Any two constraints: one afternoon to build it, and only canvas, rope, two buckets, and poles. Time and materials are both limits. (3-5-ETS1-1)"]},{std:["3-5-ETS1-2"],n:3,dur:75,dir:"Read the chart. Answer out loud.",desc:"comparing possible solutions against the criteria and constraints",html:()=>`<p class="big">Three ideas for the rain catcher, judged against what the camp needs.</p>
     <table class="bigTable"><tr><th>Idea</th><th>Water caught</th><th>Stays clean?</th><th>Build time</th><th>Uses only camp supplies?</th></tr>
     <tr><td>A: canvas sheet sloped into a bucket</td><td>9 L</td><td>yes, lid on the bucket</td><td>1 hour</td><td>yes</td></tr>
     <tr><td>B: dig a pit and line it with canvas</td><td>14 L</td><td>no, sand blows in</td><td>3 hours</td><td>yes</td></tr>
     <tr><td>C: metal roof funnel into a sealed tank</td><td>20 L</td><td>yes</td><td>1 day</td><td>no</td></tr></table>`,qs:["Which idea catches the most water? Is that enough to make it the best choice here? Explain.","Which idea best meets all of the criteria and fits inside both limits?","Idea B catches more water than idea A. Name the one criterion it fails and say why that matters."],key:["Idea C catches the most at 20 L, but it is not the best choice because it takes a day, which is longer than the camp has, and it needs materials the camp does not have. Catching the most water is only one criterion. (3-5-ETS1-2)","Idea A. It catches water, keeps it clean, takes one hour, and uses only camp supplies. (3-5-ETS1-2)","It does not keep the water clean, because sand blows into an open pit. Clean water was one of the things the catcher had to do, so more water that cannot be drunk is not an improvement. (3-5-ETS1-2)"]},{std:["3-5-ETS1-3"],n:3,dur:75,dir:"Read the test plan. Answer out loud.",desc:"planning a fair test with controlled variables and naming the failure points to improve",html:()=>`<p class="big">The crew wants to know whether a steeper canvas catches more water. They set up two catchers and poured the same amount of water over each from a watering can.</p>
     <table class="bigTable"><tr><th></th><th>Catcher 1</th><th>Catcher 2</th></tr>
     <tr><td>Slope of the canvas</td><td>gentle</td><td>steep</td></tr>
     <tr><td>Size of the canvas</td><td>2 m by 2 m</td><td>2 m by 2 m</td></tr>
     <tr><td>Water poured on</td><td>10 L</td><td>10 L</td></tr>
     <tr><td>Water collected</td><td>6 L</td><td>8 L</td></tr>
     <tr><td>What went wrong</td><td>water pooled in the middle of the canvas</td><td>water shot past the bucket at the bottom edge</td></tr></table>`,qs:["What did the crew keep the same on purpose, and what did they change? Why does that make it a fair test?","Suppose catcher 2 had used a canvas twice as big. Could you still say the slope was what made the difference? Explain.","Each catcher has a failure point in the last row. Name one change that would fix each one."],key:["They kept the canvas size and the amount of water poured the same and changed only the slope. Changing one thing at a time means any difference in the water collected can be traced to the slope. (3-5-ETS1-3)","No. Two things would have been different, the slope and the size, so you could not tell which one caused the extra water. That is no longer a fair test. (3-5-ETS1-3)","Catcher 1 pools in the middle, so tighten the canvas or add a pole under the center to push the low spot out. Catcher 2 overshoots the bucket, so add a lip or a gutter at the bottom edge or move the bucket further out. Any sensible fix tied to the stated failure counts. (3-5-ETS1-3)"]}]},{id:24,title:"Before the Ships",short:"Before Ships",parts:[{std:["HSS-5.1"],n:4,dur:110,dir:"Read the chart. Answer out loud.",desc:"describing major pre-Columbian settlements and how each region's land shaped the way people lived",html:()=>`<p class="big">Long before any ship arrived from Europe, millions of people were already living across North America. Different nations built different kinds of homes and found food in different ways, because the land around them was different.</p>
     <table class="bigTable"><tr><th>Region</th><th>What the land there gave people</th></tr>
     <tr><td>the desert Southwest</td><td>dry canyons and flat-topped mesas, very little rain, plenty of stone and clay</td></tr>
     <tr><td>the Pacific Northwest coast</td><td>thick cedar forests, rivers full of salmon, the ocean</td></tr>
     <tr><td>the Great Plains</td><td>wide grassland, huge herds of buffalo, almost no trees</td></tr>
     <tr><td>the woodlands east of the Mississippi River</td><td>forests, rivers, and soil good for growing corn, beans, and squash</td></tr></table>
     <div class="figure">${F.icon("cactus",70)}${F.icon("pine",70)}${F.icon("wheat",70)}${F.icon("corn",70)}</div>`,qs:["The Pueblo people and the cliff dwellers of the desert Southwest built with stone and dried clay. Some of it was set back into the canyon walls. Why does that fit the land they lived in?","Nations of the Pacific Northwest built big plank houses and long canoes and ate a great deal of salmon. Which two things in the chart explain that?","Many nations of the Great Plains moved camp through the year and carried their homes with them. What in the chart explains why?","Woodland peoples east of the Mississippi River farmed and lived in villages in one place. What in the chart made that possible?"],key:["Stone and clay were the materials at hand and wood was scarce, and thick walls plus the shade of a canyon keep a home cooler in a hot, dry place and shelter it from weather. Partial: naming the materials with nothing said about keeping cool is approaching. (HSS-5.1)","The cedar forests gave them wood for houses and canoes, and the rivers and ocean gave them salmon. Partial: one of the two things from the chart named is approaching. (HSS-5.1)","The buffalo herds moved, so people followed their food, and there were few trees to build with. A home like the tipi could be taken down and carried. Partial: naming the buffalo with nothing said about the lack of trees, or the reverse, is approaching. (HSS-5.1)","Good soil and rivers meant food could be grown in the same place year after year, so there was no need to move to find it. Partial: naming the soil with no link to staying in one place is approaching. (HSS-5.1)"]}]},{id:25,title:"Routes and First Meetings",short:"Routes",parts:[{std:["HSS-5.2"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"tracing the routes of early explorers of the Americas and telling what each was sent to find",html:()=>`<p class="big">After 1492, rulers in Europe paid sailors to cross the Atlantic Ocean and map what they found. Most were looking for a sea route to Asia, for gold, or for land to claim.</p>
     <table class="bigTable"><tr><th>Explorer and year</th><th>Sailing for</th><th>Where the route went</th></tr>
     <tr><td>Christopher Columbus, 1492</td><td>Spain</td><td>west across the Atlantic to islands in the Caribbean</td></tr>
     <tr><td>John Cabot, 1497</td><td>England</td><td>northwest across the Atlantic to the coast of Newfoundland</td></tr>
     <tr><td>Jacques Cartier, 1534</td><td>France</td><td>up the Saint Lawrence River into what is now Canada</td></tr>
     <tr><td>Francisco Vasquez de Coronado, 1540</td><td>Spain</td><td>north overland from Mexico into what is now the American Southwest</td></tr></table>
     <div class="figure">${F.icon("map",76)}${F.icon("compass",76)}${F.icon("sailboat",76)}</div>`,qs:["Put the four journeys in order from earliest to latest.","Columbus sailed west hoping to reach Asia. Did he reach it? What did he reach instead?","Which explorer traveled up a river rather than along an open coast. Which country paid for that voyage?","Coronado's route is the only one that did not cross the Atlantic. Why not?"],key:["Columbus 1492, Cabot 1497, Cartier 1534, Coronado 1540. Partial: three of the four in the right order is approaching. (HSS-5.2)","No. He reached islands in the Caribbean, part of the Americas, where millions of people were already living. He went on believing he had reached Asia. Partial: saying no with no account of where he actually reached is approaching. (HSS-5.2)","Cartier, up the Saint Lawrence River, paid for by France. Partial: one of the explorer and the country named is approaching. (HSS-5.2)","He started from Mexico, where Spain already had a base, and traveled north by land. He did not need to cross an ocean to get there. Partial: saying he went by land with nothing said about Spain's base in Mexico is approaching. (HSS-5.2)"]},{std:["HSS-5.3"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"describing both the cooperation and the conflict among American Indian nations and between those nations and the new settlers",html:()=>`<p class="big">When settlers arrived, American Indian nations and the newcomers sometimes worked together and sometimes came into conflict. Both happened, often in the same place and the same year.</p>
     <table class="bigTable"><tr><th>Cooperation</th><th>Conflict</th></tr>
     <tr><td>trading furs, corn, metal tools, and cloth</td><td>settlers fenced and farmed land that nations had used for generations</td></tr>
     <tr><td>nations showing settlers which crops grew well and how to travel the rivers</td><td>agreements about land were often broken by the newcomers</td></tr>
     <tr><td>nations and European powers making alliances in wartime</td><td>illnesses carried from Europe spread fast and great numbers of American Indian people died</td></tr></table>`,qs:["Name one way American Indian nations and settlers worked together.","The two sides thought about land in different ways. What was the difference, and how did it lead to conflict?","Why would an illness brought from Europe harm one group far more than the other?","Nations also made alliances and had disagreements with one another, not only with settlers. Why might one nation choose to ally with a European power?"],key:["Any item from the left column: trade, sharing knowledge of crops and rivers, or alliances in wartime. (HSS-5.3)","Many American Indian nations understood land as something a people used and cared for together, with rights to hunt or farm in a place. Settlers wanted to own a marked piece of it outright and keep everyone else off. So when settlers fenced land a nation had always used, each side believed the land was rightly theirs. Partial: naming the difference in how land was understood with no link to conflict is approaching. (HSS-5.3)","American Indian people had never been exposed to illnesses such as smallpox and measles, so they had no built-up defense against them, while Europeans had lived with those illnesses for generations. Partial: saying the illness was new with nothing said about built-up defense is approaching. (HSS-5.3)","To gain a trading partner, tools or weapons, or support against a rival nation. Nations weighed their own interests and made their own decisions, the way countries do. Partial: one reason named with nothing said about a nation weighing its own interests is approaching. (HSS-5.3)"]}]},{id:26,title:"Colonies and Why They Broke Away",short:"Colonies",parts:[{std:["HSS-5.4"],n:4,dur:150,dir:"Read the chart. Answer out loud.",desc:"identifying the political, religious, social, and economic institutions of the colonial era",html:()=>`<p class="big">Over about 150 years the thirteen colonies built up their own ways of running things.</p>
     <table class="bigTable"><tr><th>Kind of institution</th><th>What it looked like in the colonies</th></tr>
     <tr><td>political</td><td>elected assemblies such as the Virginia House of Burgesses, and town meetings in New England</td></tr>
     <tr><td>religious</td><td>Puritan congregations in New England, Quaker meetings in Pennsylvania, Catholics in Maryland, and the Anglican Church of England established by law in Virginia; Pennsylvania and Rhode Island were set up so that groups could follow their own beliefs</td></tr>
     <tr><td>social</td><td>apprenticeships, schools in some towns, and a hard line between free people and enslaved people</td></tr>
     <tr><td>economic</td><td>fishing and shipping in the north, small grain farms in the middle, large plantations in the south</td></tr></table>
     <p class="big">The large southern plantations grew tobacco, rice, and indigo, and their owners depended on the forced labor of enslaved Africans, who had been carried across the Atlantic against their will and were not free.</p>`,qs:["Give one example of a political institution in the colonies and say what the people in it did.","Name one religious institution from the chart and say which colony or region it belonged to. Then say why some people crossed the Atlantic to settle in a colony like Pennsylvania or Rhode Island.","The work was different in the north, the middle, and the south. What made it different from region to region?","Who did most of the work on the large southern plantations, and what does the word enslaved mean?"],key:["An elected assembly such as the Virginia House of Burgesses, or a New England town meeting. Colonists chose representatives who passed local laws and decided about local taxes. Partial: naming an institution with no account of what the people in it did is approaching. (HSS-5.4)","Any one correctly matched: Puritan congregations in New England, Quaker meetings in Pennsylvania, Catholics in Maryland, or the Anglican Church of England established by law in Virginia. On the second half: so that they could follow their own religious beliefs without being punished for it in the place they came from. Both halves are needed for full credit. Partial: one half without the other is approaching, so a matched institution with nothing on why people crossed sits there. (HSS-5.4)","The land and the climate. Rocky soil and good harbors in the north pushed people toward fishing and shipping, mixed soil in the middle suited grain farms, and warm weather with a long growing season in the south made large plantation crops possible. Partial: one of the three regions explained is approaching. (HSS-5.4)","Enslaved Africans. Enslaved means a person was treated by law as property: forced to work without pay, unable to leave, and not free to make their own choices. Partial: naming who did the work with no definition of enslaved is approaching. (HSS-5.4)"]},{std:["HSS-5.5"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"explaining the causes of the American Revolution",html:()=>`<p class="big">Britain had spent an enormous amount on a long war in North America. To help pay for it, Parliament in London began taxing the colonies in new ways.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1765</td><td>the Stamp Act put a tax on almost every kind of printed paper in the colonies</td></tr>
     <tr><td>1767</td><td>new taxes on imported goods such as glass, paper, and tea</td></tr>
     <tr><td>1773</td><td>colonists in Boston tipped a shipload of British tea into the harbor in protest</td></tr>
     <tr><td>1774</td><td>Parliament closed the port of Boston and took powers away from the Massachusetts assembly</td></tr></table>
     <p class="big">Colonists answered with the words no taxation without representation.</p>`,qs:["What did colonists mean by no taxation without representation?","The colonies already had elected assemblies of their own. Why did a tax passed in London trouble them so much?","Look at 1773 and 1774. How did the first lead to the second, and how did the second make things worse?","Name two causes of the American Revolution and say which you think mattered more. Give a reason."],key:["That they had no elected members in Parliament, so a body they had not voted for had no right to tax them. Partial: repeating the phrase with no account of Parliament and representation is approaching. (HSS-5.5)","Because their own assemblies had always decided their local taxes. A tax from London took that decision away from the people they had elected. Partial: saying they disliked the tax with nothing said about their own assemblies is approaching. (HSS-5.5)","The protest in Boston Harbor led Parliament to punish the whole colony by closing the port and stripping the assembly of powers. That convinced colonists elsewhere that their own assemblies could be shut down next, so the other colonies began to act together. Partial: one of the two links explained is approaching. (HSS-5.5)","Any two real causes with a reason: taxes passed without colonial representation, the loss of power by colonial assemblies, the closing of the port of Boston, British soldiers quartered in colonial towns, or the spread of ideas about rights and self-government. The ranking is the student's; the reason is what to listen for. Partial: two causes named with no ranking, or a ranking with no reason, is approaching. (HSS-5.5)"]},{std:["HSS-5.6"],n:4,dur:110,dir:"Read the timeline. Answer out loud.",desc:"telling the course of the American Revolution in order, naming consequences, and comparing how different groups saw it",html:()=>`<p class="big">The war lasted eight years.</p>
     <table class="bigTable"><tr><th>Year</th><th>Event</th></tr>
     <tr><td>1775</td><td>fighting begins at Lexington and Concord, and the Continental Congress puts George Washington in command</td></tr>
     <tr><td>1776</td><td>the Declaration of Independence states that the colonies are free and independent states</td></tr>
     <tr><td>1777</td><td>an American win at Saratoga convinces France to join the war as an ally</td></tr>
     <tr><td>1781</td><td>the British army surrenders at Yorktown</td></tr>
     <tr><td>1783</td><td>the Treaty of Paris ends the war and Britain recognizes the United States</td></tr></table>`,qs:["Put these three in order: the Treaty of Paris, the Declaration of Independence, the surrender at Yorktown.","Why did the win at Saratoga matter so much even though the war went on for four more years?","Not everyone in the colonies wanted independence. Loyalists stayed loyal to Britain. American Indian nations and enslaved people made their own choices about which side to support. Why would someone who was not free weigh that choice differently?","Name one consequence of the war."],key:["The Declaration of Independence in 1776, the surrender at Yorktown in 1781, then the Treaty of Paris in 1783. Partial: the three in the right order with no years is approaching. (HSS-5.6)","It convinced France to join as an ally, which brought money, ships, and soldiers to the American side. Partial: naming France with nothing said about what the alliance brought is approaching. (HSS-5.6)","An enslaved person's first question was which side offered freedom. Britain promised freedom to some who left their owners and joined the British side, and thousands did. Others served on the American side hoping to be freed afterward. American Indian nations asked which side was less likely to take their land. Partial: saying the choice was harder with no account of what either side offered is approaching. (HSS-5.6)","Any real consequence: the United States became an independent country, Britain gave up its claim to the land east of the Mississippi River, many Loyalists left for Canada and elsewhere, the new country carried heavy war debts and had to build a government, and slavery continued even though the Declaration had said all men are created equal. Partial: saying the colonists won with no consequence beyond the result is approaching. (HSS-5.6)"]}]},{id:27,title:"A Plan of Government and a Country Moving West",short:"New Nation",parts:[{std:["HSS-5.7"],n:4,dur:110,dir:"Read the notes. Answer out loud.",desc:"describing the people and events behind the U.S. Constitution and why it matters",html:()=>`<p class="big">The first plan of government, the Articles of Confederation, left the national government too weak to collect taxes or settle arguments between states. In 1787 delegates met in Philadelphia to write a new one.</p>
     <table class="bigTable"><tr><th>Person</th><th>What they did at the convention</th></tr>
     <tr><td>George Washington</td><td>led the convention and later became the first president</td></tr>
     <tr><td>James Madison</td><td>shaped the plan and kept the record of the debates</td></tr>
     <tr><td>Benjamin Franklin</td><td>the oldest delegate, pushed the states toward compromise</td></tr></table>
     <p class="big">The Constitution split the government into three branches. The first ten amendments, called the Bill of Rights, list rights the government may not take away.</p>`,qs:["Name the three branches of government and say what each one does.","Why did the delegates meet at all? What was wrong with the Articles of Confederation?","What is the Bill of Rights, and why did some states insist on it before they would agree?","When the Constitution was signed, many people in the country could not vote. That included women, enslaved people, and many men who owned no property. How did that change afterward?"],key:["Legislative, which is Congress and makes the laws. Executive, which is the president and carries the laws out. Judicial, which is the courts and decides what the laws mean. Partial: two of the three branches named with their jobs is approaching. (HSS-5.7)","Under the Articles the national government could not collect taxes, could not raise money to pay its war debts, and could not settle disputes between states. It was too weak to do its job. Partial: saying the Articles were weak with no example of what the government could not do is approaching. (HSS-5.7)","The first ten amendments, listing rights the government cannot take away, such as speech, the press, and a fair trial. Several states would not ratify the Constitution without that written promise. Partial: naming the Bill of Rights with nothing said about why states insisted on it is approaching. (HSS-5.7)","Amendments were added over many years and the vote was widened by law: to men of all races after the Civil War, to women in 1920, and to citizens aged 18 and over in 1971. Each change took long campaigning by the people who had been left out. Partial: one of the three widenings named is approaching. (HSS-5.7)"]},{std:["HSS-5.8"],n:4,dur:100,dir:"Read the chart. Answer out loud.",desc:"tracing settlement and immigration patterns from 1789 to the mid-1800s and the role of land, geography, and transport",html:()=>`<p class="big">In the sixty years after 1789 the country spread west and its population grew fast.</p>
     <table class="bigTable"><tr><th>Year</th><th>What happened</th></tr>
     <tr><td>1803</td><td>the Louisiana Purchase roughly doubles the size of the country</td></tr>
     <tr><td>1804 to 1806</td><td>Lewis and Clark travel west and map rivers and routes, guided in part by Sacagawea</td></tr>
     <tr><td>1825</td><td>the Erie Canal opens, linking the Great Lakes to the Hudson River and the port of New York</td></tr>
     <tr><td>1830</td><td>the Indian Removal Act forces nations of the Southeast off their homelands to land west of the Mississippi River</td></tr>
     <tr><td>1840s</td><td>railroads spread, and large numbers of people arrive from Ireland and Germany</td></tr></table>
     <div class="figure">${F.icon("canoe",72)}${F.icon("bridge",72)}${F.icon("truck",72)}</div>`,qs:["Name two reasons a family in 1840 might pack up and move west.","The Erie Canal cut the cost of moving a ton of wheat from Buffalo to New York by about nine tenths. Why would that change where people chose to settle?","Rivers, flat land, and mountain passes shaped where the routes went. Give one example from the chart of geography deciding a route.","The chart also records the Indian Removal Act. What happened to the nations living on land that settlers wanted?"],key:["Any two economic or practical incentives: cheap or free farmland, better soil, work on canals and railroads, a trade or shop in a growing town, or joining relatives who had already gone. Partial: one reason named is approaching. (HSS-5.8)","Cheap transport meant a farmer far inland could sell a crop at a port and still make money, so settling inland became worth doing and towns grew along the canal and the lakes. Partial: saying it was cheaper with no link to where people settled is approaching. (HSS-5.8)","Any example: the canal was dug to join the Great Lakes to the Hudson River because that was the low route through the hills; Lewis and Clark followed the Missouri River west because rivers were the easiest way to travel; settlers crossed the mountains at passes rather than over the peaks. Partial: a route named with no geography behind it is approaching. (HSS-5.8)","They were forced to leave. Nations of the Southeast, among them the Cherokee, Creek, Choctaw, Chickasaw, and Seminole, were made to travel hundreds of miles west, and thousands of people died on the journey, which the Cherokee call the Trail of Tears. Land taken this way was opened to settlers. Partial: saying they had to move with no account of the distance, the deaths or who took the land is approaching. (HSS-5.8)"]},{std:["HSS-5.9"],n:5,dur:90,dir:"Answer out loud. A map is fine to look at.",desc:"locating coastal states and naming their capitals",html:()=>`<div class="figure">${F.icon("globe",96)}${F.icon("flag",96)}${F.icon("map",96)}</div>
     <p class="big">Questions about the states and their capital cities.</p>`,qs:["How many states are there in the United States today?","What state do you live in, and what is its capital city?","Name the capital of Texas and the capital of New York.","Name three states that touch the Pacific Ocean.","Which state reaches farthest north, and which state is a chain of islands?"],key:["50 (HSS-5.9)","The student's own state and its capital. For California the capital is Sacramento. (HSS-5.9)","Austin, Texas and Albany, New York. Note if the student names the largest city instead, which is the usual slip. Partial: one of the two capitals right is approaching. (HSS-5.9)","Any three of California, Oregon, Washington, Alaska, and Hawaii. Partial: two of the three states named is approaching. (HSS-5.9)","Alaska reaches farthest north. Hawaii is a chain of islands. Partial: one of the two answered is approaching. (HSS-5.9)"]}]}];const LEVELUPS={3:{id:"L3",title:"Level Up: Word Choice",std:["RL.6.4"],needs:["RL.5.4"],n:1,dir:"Answer out loud.",html:()=>`<p class="passage sm">${PASSAGE}</p><ol class="qlist"><li>The author wrote that Marco’s voice was “steadier now.” Why is steadier a better word there than louder? What feeling does it give the story?</li></ol>`,key:["Steadier shows he calmed down and felt more confident, not just that he got louder. The feeling shifts from nervous to calm. (RL.6.4, impact of word choice on tone)"]},6:{id:"L6",title:"Level Up: Power Up",std:["6.EE.A.1"],needs:["5.OA.A.1"],n:3,dir:"Solve on your paper. Tell your teacher your answers.",html:()=>`<ol class="qlist"><li>5² = ?</li><li>2³ + 4 = ?</li><li>Write 3 × 3 × 3 × 3 with an exponent. Then find its value.</li></ol>`,key:["25 (6.EE.A.1)","12, because 2³ is 8 and 8 + 4 = 12 (6.EE.A.1)","3⁴, which is 81 (6.EE.A.1)"]},9:{id:"L9",title:"Level Up: Fraction Box",std:["6.G.A.2"],needs:["5.MD.C.5"],n:2,dir:"Solve on your paper. Tell your teacher your answers.",html:()=>`<ol class="qlist"><li>A box is 2 1/2 feet long, 2 feet wide, and 3 feet tall. What is its volume?</li><li>A tiny cube has edges that are 1/2 inch long. What is its volume?</li></ol>`,key:["15 cubic feet, from 2 1/2 × 2 × 3 (6.G.A.2)","1/8 cubic inch, from 1/2 × 1/2 × 1/2 (6.G.A.2)"]},10:{id:"L10",title:"Level Up: Four Quadrants",std:["6.NS.C.6"],needs:["5.G.A.1"],n:3,dir:"Look at the grid. Answer out loud.",html:()=>`<div class="figure">${grid4()}</div><ol class="qlist"><li>What are the coordinates of point P?</li><li>What are the coordinates of point Q?</li><li>Point R is at (−2, −3). Which two ways do you move from the origin to get there?</li></ol>`,key:["(−3, 2) (6.NS.C.6)","(2, −4) (6.NS.C.6)","2 to the left, then 3 down (6.NS.C.6)"]},11:{id:"L11",title:"Level Up: Pronoun Fix",std:["L.6.1"],needs:["L.5.1"],n:3,dir:"Say each sentence out loud the correct way.",html:()=>`<ol class="qlist"><li>Fix it: “Marco and me set up the table.”</li><li>Fix it: “The judge gave the ribbon to Jade and I.”</li><li>Finish it with a word that shows Jade did it on her own: “Jade ____ built the filter.”</li></ol>`,key:["Marco and I (L.6.1, subjective case)","Jade and me (L.6.1, objective case)","herself (L.6.1, intensive pronoun)"]}};const SPLITS={incredible:"in·cred·i·ble",photographer:"pho·tog·ra·pher",misunderstood:"mis·un·der·stood",unbreakable:"un·break·a·ble",geology:"ge·ol·o·gy",transportation:"trans·por·ta·tion",reconstruction:"re·con·struc·tion",impossibility:"im·pos·si·bil·i·ty",responsibility:"re·spon·si·bil·i·ty",extraordinary:"ex·tra·or·di·nar·y",flemberation:"flem·ber·a·tion",unpreskable:"un·presk·a·ble"};function tbl(rows,head){return`<div style="overflow-x:auto"><table class="chart">${head?`<tr>${head.map(h=>`<th>${h}</th>`).join("")}</tr>`:""}${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</table></div>`}function multChart(){let r=[];for(let i=0;i<=12;i++){const row=[];for(let j=0;j<=12;j++){row.push(i===0&&j===0?"×":i===0?`<b>${j}</b>`:j===0?`<b>${i}</b>`:i*j)}r.push(row)}return`<div style="overflow-x:auto"><table class="chart mult">${r.map((row,i)=>`<tr>${row.map((c,j)=>i===0||j===0?`<th>${c}</th>`:`<td>${c}</td>`).join("")}</tr>`).join("")}</table></div>`}function pvChart(){const head=["Thousands","Hundreds","Tens","Ones",".","Tenths","Hundredths","Thousandths"],vals=["1,000","100","10","1",".","0.1","0.01","0.001"],fr=["","","","",".","1/10","1/100","1/1000"];const cell=(c,i,tag,extra)=>{const dec=i>=4;const st=`padding:${tag==="th"?"8px 4px":"10px 4px"};text-align:center;${i===4?"width:20px;font-size:1.4rem;font-weight:700;":""}${dec&&i>4?"background:var(--sea-soft);":""}${extra||""}`;return`<${tag} style="${st}">${c}</${tag}>`};const row=(arr,tag,extra)=>`<tr>${arr.map((c,i)=>cell(c,i,tag,extra)).join("")}</tr>`;return`<div class="tool-scroll"><table class="chart" style="width:100%;font-size:.95rem">${row(head,"th","font-size:.74rem;white-space:nowrap;padding-left:1px;padding-right:1px;")}${row(vals,"td","font-weight:700;")}${row(fr,"td","font-size:.85rem;")}${row(["","","","",".","","",""],"td","height:54px;font-size:1.8rem;font-weight:700;")}</table></div><p class="small">The bottom row is for digits. Each place to the left is worth 10 times as much. Each place to the right is worth 1/10 as much. The last place, <b>thousandths</b>, is the third one after the point.</p>`}function strips(){const dens=[1,2,3,4,6,8,12],W=600,h=40;let s=`<svg viewBox="56 0 ${W+8} ${dens.length*(h+6)+4}" width="100%" style="max-width:640px" role="img" aria-label="Fraction strips">`;dens.forEach((d,r)=>{for(let k=0;k<d;k++){const x=60+k*W/d,y=2+r*(h+6);s+=`<rect x="${x}" y="${y}" width="${W/d}" height="${h}" fill="${["#F6D98A","#CFE7EC","#F9C9BE","#D6ECCF","#E6D6F2","#FCE2B5","#D9E4F5"][r]}" stroke="#1d3a44" stroke-width="1.5"/><text x="${x+W/d/2}" y="${y+h/2}" text-anchor="middle" dominant-baseline="central" font-size="${d>8?15:18}" fill="#15303A">${d===1?"1":"1/"+d}</text>`}});return s+"</svg>"}function coordMini(){return`<svg viewBox="0 -8 260 208" width="260" role="img" aria-label="Across then up"><line x1="30" y1="170" x2="240" y2="170" stroke="var(--ink)" stroke-width="3"/><line x1="30" y1="170" x2="30" y2="15" stroke="var(--ink)" stroke-width="3"/><text x="244" y="176" font-size="18" fill="var(--ink)">x</text><text x="24" y="12" font-size="18" fill="var(--ink)">y</text><text x="8" y="192" font-size="14" fill="var(--ink)">(0,0)</text><path d="M30 170 H150" stroke="var(--coral)" stroke-width="5" marker-end="url(#ah)"/><path d="M150 170 V70" stroke="var(--sea)" stroke-width="5" marker-end="url(#ah)"/><circle cx="150" cy="70" r="8" fill="var(--coral)"/><text x="44" y="160" font-size="15" fill="var(--ink)">1st: across</text><text x="158" y="125" font-size="15" fill="var(--ink)">2nd: up</text><defs><marker id="ah" viewBox="0 0 10 10" refX="5" refY="5" markerWidth="4" markerHeight="4" orient="auto"><path d="M0 0 L10 5 L0 10 z" fill="var(--ink)"/></marker></defs></svg>`}const TOOLS={chunk:{name:"Show syllable chunks",std:["RF.5.3"],html:()=>`<p data-tpk="chunk" style="margin:0;font-size:1.15rem">Each word now shows with dots between its syllables. Close this tool to hide the chunks again.</p>`},prefix:{name:"Prefix and suffix chart",std:["RF.5.3"],html:()=>tbl([["un-, in-, im-, dis-","not"],["re-","again"],["mis-","wrongly"],["trans-","across"],["-tion","act or result of"],["-able, -ible","can be"],["-ity","state of being"],["-er","person who"]],["Word part","Means"])+`<p class="chart-note">Cover the prefix and suffix, read the middle, then put it back together.</p>`},ruler:{name:"Reading ruler (one sentence at a time)",std:["RF.5.4"],html:()=>`<div data-tpk="ruler"><div class="row"><button class="chip" id="rulerBack">Back a sentence</button><button class="chip" id="rulerNext">Next sentence</button></div><p class="small">One sentence is lit up at a time. Sentence ${rulerIdx+1} of ${SENTS.length}. Close this tool to show the whole story again.</p></div>`,bind:(b,r)=>{b.querySelector("#rulerBack").onclick=()=>{rulerIdx=Math.max(0,rulerIdx-1);paintPsg();r()};b.querySelector("#rulerNext").onclick=()=>{rulerIdx=Math.min(SENTS.length-1,rulerIdx+1);paintPsg();r()}}},quote:{name:"Quote it sentence frames",std:["RL.5.1","RI.5.1"],html:()=>`<ul class="frames"><li>The text says, “______.”</li><li>I know ______ because the text says, “______.”</li><li>The words “______” show that ______.</li></ul><p class="chart-note">🔍 Find it → 👆 point to it → 🗣 read the exact words.</p>`},fig:{name:"Figurative language chart",std:["RL.5.4"],html:()=>tbl([["🔗 Simile","Compares two things using like or as","Her smile was like sunshine."],["🎭 Metaphor","Says one thing IS another thing","The classroom was a zoo."],["❓ What it means","Ask: what is really being compared? How does it feel?","A zoo = loud and wild"]],["Type","What it does","Example"])},pv:{name:"Place value chart",std:["5.NBT.A.1","5.NBT.A.3"],html:pvChart},dec:{name:"Decimal anchor chart",std:["5.NBT.A.3"],html:()=>`<ul class="frames"><li><b>Read it:</b> say the whole number, say “and” at the decimal point, then read the digits and say the last place. 2.18 = two and eighteen hundredths.</li><li><b>Expanded form:</b> 3.14 = 3 × 1 + 1 × (1/10) + 4 × (1/100)</li><li><b>Compare:</b> line up the decimal points, add zeros so they are the same length, then compare place by place from the left. 0.70 vs 0.07</li></ul>`},ops:{name:"Order of operations chart",std:["5.OA.A.1"],html:()=>`<ol class="frames"><li>Work from the inside out: ( ) parentheses, then [ ] brackets, then { } braces.</li><li>Then × and ÷, left to right.</li><li>Then + and −, left to right.</li></ol><p class="chart-note">Example: 2 × [5 + (3 − 1)] → 2 × [5 + 2] → 2 × 7 = 14</p>`},mult:{name:"Multiplication chart",std:["5.NBT.A.1","5.OA.A.1","5.NF.A.1","5.NF.A.2","5.NF.B.3","5.NF.B.4","5.MD.C.3","5.MD.C.5","6.EE.A.1","6.G.A.2"],html:multChart},frac:{name:"Adding fractions steps",std:["5.NF.A.1","5.NF.A.2"],html:()=>`<ol class="frames"><li>Find a common denominator. List multiples: 4: 4, 8, <b>12</b> &nbsp; 6: 6, <b>12</b></li><li>Make equivalent fractions. Multiply top and bottom by the same number: 1/4 = 3/12, 1/6 = 2/12</li><li>Add or subtract the numerators. Keep the denominator: 3/12 + 2/12 = 5/12</li><li>Mixed numbers: add the wholes, add the fractions. Simplify or change an improper fraction to a mixed number.</li></ol><p class="chart-note">Check it: is the answer close to 0, 1/2, or 1? Does that make sense?</p>`},strips:{name:"Fraction strips",std:["5.NF.A.1","5.NF.A.2","5.NF.B.3","5.NF.B.4"],html:strips},fdiv:{name:"Fractions as division and multiplying chart",std:["5.NF.B.3","5.NF.B.4"],html:()=>`<ul class="frames"><li><b>A fraction is division:</b> 2/5 = 2 ÷ 5. 2 pizzas shared by 5 people = 2/5 of a pizza each. 🍕🍕 ÷ 👤👤👤👤👤</li><li><b>Improper to mixed:</b> 7/3 → 7 ÷ 3 = 2 R1 → 2 1/3</li><li><b>Multiply fractions:</b> top × top, bottom × bottom. 2/3 × 1/4 = 2/12</li><li><b>Whole number:</b> write it over 1. 3/5 × 2 = 3/5 × 2/1 = 6/5</li><li><b>“Of” means multiply:</b> 1/3 of 1/2 = 1/3 × 1/2</li></ul>`},vol:{name:"Volume anchor chart",std:["5.MD.C.3","5.MD.C.5"],html:()=>`<div class="figure" style="margin:0">${prism(2,2,1,28)}</div><ul class="frames"><li>Volume = how many unit cubes fill a solid. Units: cubic units, cubic cm (cm³), cubic inches.</li><li>V = length × width × height</li><li>V = B × h (B = area of the base)</li><li>Two boxes stuck together? Find each volume and add them.</li></ul>`},coord:{name:"Coordinate grid chart",std:["5.G.A.1"],html:()=>`<div class="figure" style="margin:0">${coordMini()}</div><ul class="frames"><li>(x, y): the first number goes <b>across</b> on the x-axis, the second goes <b>up</b> on the y-axis.</li><li>The origin is (0, 0), where the axes cross.</li><li>Walk before you climb.</li></ul>`},tense:{name:"Verb tense timeline",std:["L.5.1"],ok:st=>st.id===11,html:()=>tbl([["⏪ Past perfect","had + verb","I had eaten before the game."],["⏺ Present perfect","has/have + verb","I have eaten already."],["⏩ Future perfect","will have + verb","I will have eaten by 6."],["⚠ Tense shift","Keep the same time in a sentence","Yesterday I ran and jumped."]],["Tense","How to build it","Example"])},pos:{name:"Parts of speech chart",std:["L.5.1"],ok:st=>st.id===11,html:()=>tbl([["Conjunction","joins words or ideas","and, but, or, so, because"],["Correlative pair","conjunctions that work as a team","either/or, neither/nor, both/and, not only/but also"],["Preposition","shows where or when","in, on, under, across, through, after"],["Interjection","shows feeling","Oh! Hey! Yikes!"]],["Part of speech","Job","Examples"])},notes:{name:"Notes organizer",std:["W.5.8"],html:()=>tbl([["1.","",""],["2.","",""],["3.","",""]],["#","Note (my own words)","Text A or B"])+`<p class="chart-note">Sources: Text A: ______ &nbsp; Text B: ______</p>`},dict:{name:"Typing and voice typing help",std:["W.5.8","W.5.1","W.5.2","W.5.3"],html:()=>`<ul class="frames"><li>Type in a Google Doc or the meeting chat and send it to your teacher.</li><li>Google Docs voice typing: Tools, then Voice typing, then click the microphone.</li><li>Windows: press the Windows key + H.</li><li>Mac: Edit menu, then Start Dictation (or press the microphone or Fn key twice).</li><li>iPad or phone: tap the microphone on the keyboard.</li><li>Chromebook: Search + D (dictation must be on in accessibility settings).</li></ul>`},sumup:{name:"Summary picture cues and frame",std:["SL.5.2"],html:()=>`<p class="huge" style="font-size:2.6rem;margin:6px 0">${F.icon("fire",42)} → ${F.icon("volcano",42)} → ${F.icon("mountain",42)} → ${F.icon("island",42)} → ${F.icon("question",42)}</p><ul class="frames"><li>This is mostly about ______.</li><li>First, ______. Then, ______. Finally, ______.</li></ul>`},oreo:{name:"Opinion organizer and word bank",std:["SL.5.4","W.5.1"],html:()=>tbl([["O","Opinion","I think ______."],["R","Reason","One reason is ______."],["E","Example","For example, ______."],["O","Opinion again","That is why ______."]],["","Part","Starter"])+`<p class="chart-note">Linking words: for example, also, specifically, because of this, therefore, consequently</p>`},info:{name:"Informative organizer and word bank",std:["W.5.2"],html:()=>tbl([["Title","Name your topic"],["Intro","What is this about? Why does it matter?"],["Facts","Fact 1, Fact 2, Fact 3 (group ones that go together)"],["Closing","Sum it up in one sentence"]],["Part","What to write"])+`<p class="chart-note">Linking words: also, another, for example, especially, in contrast, as a result</p><p class="chart-note">Volcano words: magma, lava, hot spot, erupt, Pacific Plate &nbsp; Monarch words: migrate, milkweed, nectar, caterpillar, cluster</p>`},story:{name:"Story map and word bank",std:["W.5.3"],html:()=>tbl([["🎬 Beginning","Who is it about? Where are they? What is going on?"],["⚡ Middle","What made you nervous? What happened next? What did people say?"],["🏁 End","How did it turn out? How did you feel?"]],["Part","Questions"])+`<p class="chart-note">Time words: first, at first, later, after that, suddenly, finally &nbsp; Senses: 👀 saw 👂 heard ✋ felt 👃 smelled</p><p class="chart-note">Dialogue: “I can’t do this,” I whispered.</p>`}};const SUP_CAVEATS=[{t:"chunk",std:["RF.5.3"],msg:"With the syllable chunks showing, this stop shows the student can read words that are already split, not break long words apart alone."},{t:"ruler",std:["RF.5.4"],msg:"A timed read with the reading ruler is not a clean fluency baseline. The WCPM line in Notes says it was read with support."},{t:"fig",std:["RL.5.4"],msg:"The figurative language chart tells what a simile and a metaphor are, so count the simile or metaphor question as supported."},{t:"pv",std:["5.NBT.A.1"],msg:"The place value chart states the 10 times and 1/10 rule, which is what 5.NBT.A.1 checks. Count this stop as supported, not independent."},{t:"dec",std:["5.NBT.A.3"],msg:"The decimal chart shows how to read, expand, and compare decimals. Count this stop as supported, not independent."},{t:"ops",std:["5.OA.A.1"],msg:"The order of operations chart gives the order to work in. Count this stop as supported, not independent."},{t:"frac",std:["5.NF.A.1","5.NF.A.2"],msg:"The steps chart walks through finding a common denominator. Count the fraction answers as supported, not independent."},{t:"fdiv",std:["5.NF.B.3","5.NF.B.4"],msg:"This chart gives the rules for fractions as division and for multiplying fractions. Count this stop as supported, not independent."},{t:"vol",std:["5.MD.C.3","5.MD.C.5"],msg:"The volume chart tells what volume means and gives the formulas. Count those answers as supported."},{t:"coord",std:["5.G.A.1"],msg:"The coordinate chart shows the origin and the across-then-up rule. Count those questions as supported."},{t:"tense",std:["L.5.1"],msg:"The verb tense timeline shows how to build each tense. Count the tense items as supported."},{t:"pos",std:["L.5.1"],msg:"The parts of speech chart lists example words. Count the either/or item and the parts of speech item as supported."},{t:"sumup",std:["SL.5.2"],msg:"The picture cues give the order of the events, so count the order check as supported."},{t:"oreo",msg:"The organizer and word bank supply the structure, the linking words, and the closing. Count those checks as supported, not independent."},{t:"info",msg:"The organizer and word bank supply the structure, the linking words, and the topic words. Count those checks as supported, not independent."},{t:"story",msg:"The story map and word bank supply the structure, the time words, and a dialogue model. Count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.5.1","W.5.2","W.5.3","W.5.8"],msg:"If an adult wrote for the student, the ideas are the student’s but the spelling and punctuation are not. Pick Dictated in the box under the writing."}];const PASSAGE_STD=["RL.5.1","RL.5.4","RI.5.1","RI.5.9","RL.6.4"];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
